def cells(g,c): return {(i,j) for i in range(len(g)) for j in range(len(g[0])) if g[i][j]==c}
def noise_color(g):
    R=rot(g)
    return [c for c in {x for r in g for x in r} if cells(g,c)!=cells(R,c)]
def f(g):
    nc=set(noise_color(g))
    R=rot(g); FH=fliph(g); FV=flipv(g)
    h,w=len(g),len(g[0])
    out=[]
    for i in range(h):
        row=[]
        for j in range(w):
            if g[i][j] in nc:
                vs=[v for v in (R[i][j],FH[i][j],FV[i][j]) if v not in nc]
                row.append(Counter(vs).most_common(1)[0][0])
            else:
                row.append(g[i][j])
        out.append(row)
    return out
