def f(g):
    h,w=len(g),len(g[0])
    R=rot(g)
    mism=[(i,j) for i in range(h) for j in range(w) if g[i][j]!=R[i][j]]
    colors={x for r in g for x in r}
    cand=[c for c in colors if all(c in (g[i][j],R[i][j]) for i,j in mism)]
    assert len(cand)==1, cand
    c=cand[0]
    FH=fliph(g); FV=flipv(g)
    out=[]
    for i in range(h):
        row=[]
        for j in range(w):
            if g[i][j]==c:
                vs=[v for v in (R[i][j],FH[i][j],FV[i][j]) if v!=c]
                row.append(Counter(vs).most_common(1)[0][0])
            else:
                row.append(g[i][j])
        out.append(row)
    return out
